#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# urlencode VALUE percent-encodes VALUE in pure bash, so secrets never appear
# in a process listing.
urlencode() {
  local s="$1" out="" c i
  for (( i = 0; i < ${#s}; i++ )); do
    c="${s:i:1}"
    case "$c" in
      [a-zA-Z0-9.~_-]) out+="$c" ;;
      *) printf -v c '%%%02X' "'$c"; out+="$c" ;;
    esac
  done
  printf '%s' "$out"
}

# normalize_store turns "foo", "foo.myshopify.com" or a URL into foo.myshopify.com.
normalize_store() {
  local s="${1#https://}"; s="${s#http://}"; s="${s%%/*}"
  [[ "$s" == *.myshopify.com ]] || s="$s.myshopify.com"
  printf '%s' "$s"
}

REQUIRED_SCOPES=(read_products read_inventory read_locations write_inventory)
API_VERSION="2026-10"

run_wizard() {

cd "$(dirname "$0")/.."   # .env lives at the repo root

TOTAL_STAGES=7

banner "storewarden: Shopify dev store setup"

# ── 1 ────────────────────────────────────────────────────────────────────────
stage "Sign in to the Dev Dashboard"
say "storewarden talks to one Shopify development store through an app you own."
say "The store and the app must be in the SAME organization, or the token request fails."
open_url "https://dev.shopify.com/dashboard"
step "Sign in (create a free Shopify Partner account if you don't have one)."
step "Note which organization you're in (top-left). Use it for every step below."
pause "Signed in? Press Enter."

# ── 2 ────────────────────────────────────────────────────────────────────────
stage "Create the dev store"
say "Shopify CLI creates a Basic-plan dev store with demo products and inventory."
note "Basic has the smallest rate-limit bucket, which is the most realistic place to test throttling."
warn "A dev store's myshopify.com name can't be changed later."
if command -v shopify >/dev/null 2>&1 && confirm "Create a new dev store now? (answer N if you already have one)"; then
  ask STORE_NAME "Store name (e.g. storewarden-dev):"
  step "The CLI may open a browser to log in. Pick the same organization as stage 1."
  shopify store create dev --name "$STORE_NAME" --plan basic --demo-data \
    || warn "store creation failed or was cancelled. Create it in Dev Dashboard → Stores → Create store → Dev, then continue."
else
  note "Using an existing store. (No CLI? Dev Dashboard → Stores → Create store → Dev → Basic.)"
fi
ask SHOPIFY_STORE "Store domain (e.g. storewarden-dev.myshopify.com):"
SHOPIFY_STORE=$(normalize_store "$SHOPIFY_STORE")
write_env SHOPIFY_STORE "$SHOPIFY_STORE"

# ── 3 ────────────────────────────────────────────────────────────────────────
stage "Create the app"
note "Dev Dashboard, not Shopify CLI: Shopify recommends the dashboard for API-only apps with no admin UI."
open_url "https://dev.shopify.com/dashboard"
step "In the left sidebar, select Apps, then Create app (top right)."
step "Choose Start from Dev Dashboard."
step "Name it storewarden, then select Create."
pause "App created? Press Enter."

# ── 4 ────────────────────────────────────────────────────────────────────────
stage "Release a version with the access scopes"
say "A version is a snapshot of the app's configuration. The app can't be installed until one is released."
step "Open the app's Versions page and create a version."
step "App URL: leave the default (storewarden isn't embedded in the admin)."
step "Webhooks API version: $API_VERSION."
step "Scopes: add exactly these:"
for s in "${REQUIRED_SCOPES[@]}"; do note "    $s"; done
note "No customer or order scopes: storewarden never reads protected customer data."
step "Select Release."
pause "Version released? Press Enter."

# ── 5 ────────────────────────────────────────────────────────────────────────
stage "Install the app on the store"
step "On the app's page, select Install app at the top of the Installs card."
step "Choose $SHOPIFY_STORE, then select Install."
note "If you change scopes later, release a new version and approve it in the store admin."
pause "Installed? Press Enter."

# ── 6 ────────────────────────────────────────────────────────────────────────
stage "Copy the app credentials"
step "On the app, open Settings. The Credentials card shows the Client ID and Client secret."
ask SHOPIFY_CLIENT_ID "Paste the Client ID:"
ask_secret SHOPIFY_CLIENT_SECRET "Paste the Client secret (hidden):"
write_env SHOPIFY_CLIENT_ID "$SHOPIFY_CLIENT_ID"
write_env SHOPIFY_CLIENT_SECRET "$SHOPIFY_CLIENT_SECRET"
note "No GitHub secrets: CI uses fakes and never talks to Shopify."

# ── 7 ────────────────────────────────────────────────────────────────────────
stage "Verify: token, scopes, and a test query"
say "Requesting a token with the client credentials grant (it's never printed)…"
local body resp code token scopes missing=() s
body="grant_type=client_credentials&client_id=$(urlencode "$SHOPIFY_CLIENT_ID")&client_secret=$(urlencode "$SHOPIFY_CLIENT_SECRET")"
resp=$(printf '%s' "$body" | curl -sS -w '\n%{http_code}' -X POST \
  -H 'Content-Type: application/x-www-form-urlencoded' --data-binary @- \
  "https://$SHOPIFY_STORE/admin/oauth/access_token") || resp=$'\n000'
code="${resp##*$'\n'}"; resp="${resp%$'\n'*}"
if [[ "$code" != 200 ]]; then
  warn "token request failed (HTTP $code): $(jq -r '.error_description // .error // .' <<<"$resp" 2>/dev/null || echo "$resp")"
  note "app_not_installed → redo stage 5. invalid_client → recheck stage 6."
  note "Different organizations → the store and app must share one. Fix it, then re-run: Enter keeps saved values."
  exit 1
fi
token=$(jq -r '.access_token' <<<"$resp")
scopes=",$(jq -r '.scope' <<<"$resp"),"
for s in "${REQUIRED_SCOPES[@]}"; do
  # A write_ scope implies its read_ scope, and Shopify may report only the write one.
  [[ "$scopes" == *",$s,"* || "$scopes" == *",${s/read_/write_},"* ]] || missing+=("$s")
done
printf '  %s✓%s token issued (expires in %ss)\n' "$GREEN" "$RESET" "$(jq -r '.expires_in' <<<"$resp")"
if (( ${#missing[@]} )); then
  warn "missing scopes: ${missing[*]}. Release a new version with them (stage 4) and approve it on the store."
  exit 1
fi
printf '  %s✓%s scopes: %s\n' "$GREEN" "$RESET" "$(jq -r '.scope' <<<"$resp")"

resp=$(printf '%s' '{"query":"{ shop { name } productsCount { count } }"}' | curl -sS -X POST \
  -H 'Content-Type: application/json' -H @<(printf 'X-Shopify-Access-Token: %s\n' "$token") \
  --data-binary @- "https://$SHOPIFY_STORE/admin/api/$API_VERSION/graphql.json") || resp='{}'
if jq -e '.data.shop.name' <<<"$resp" >/dev/null 2>&1; then
  printf '  %s✓%s shop "%s" with %s products\n' "$GREEN" "$RESET" \
    "$(jq -r '.data.shop.name' <<<"$resp")" "$(jq -r '.data.productsCount.count' <<<"$resp")"
  [[ "$(jq -r '.data.productsCount.count' <<<"$resp")" == 0 ]] \
    && warn "no products yet. Add a few in the store admin so the inventory Tools have something to read."
else
  warn "test query failed: $(jq -c '.errors // .' <<<"$resp" 2>/dev/null || echo "$resp")"
  exit 1
fi
unset token
pause "All good. Press Enter for the summary."

finish
}

run_wizard "$@"; exit
